class Solution {
public:
    int findPattern(InfiniteStream* stream, vector<int>& pattern) {
        int m = pattern.size();
        vector<int> pi(m);
        for (int i = 1, j = 0; i < m; ++i) {
            while (j && pattern[i] != pattern[j]) j = pi[j - 1];
            if (pattern[i] == pattern[j]) ++j;
            pi[i] = j;
        }
        int j = 0;
        for (int i = 0; ; ++i) {
            int bit = stream->next();
            while (j && bit != pattern[j]) j = pi[j - 1];
            if (bit == pattern[j]) ++j;
            if (j == m) return i - m + 1;
        }
    }
};
